void VocaEditor::resized(){if(!ready||knobs.size()!=voca::NumKnobs)return;const float s=getWidth()/W;for(size_t i=0;i<knobs.size();++i){const auto& a=voca::specs[i];knobs[i]->setBounds(juce::Rectangle<float>((a.x-a.r)*s,(a.y-a.r)*s,2*a.r*s,2*a.r*s).toNearestInt());}for(size_t i=0;i<powers.size();++i){const auto& m=voca::modules[i];powers[i]->setBounds(juce::Rectangle<float>((m.x-13)*s,(m.y-13)*s,26*s,26*s).toNearestInt());}for(size_t i=0;i<combos.size();++i){const auto& c=voca::choices[i];combos[i]->setBounds(juce::Rectangle<float>(c.x*s,c.y*s,c.w*s,30*s).toNearestInt());}for(int i=0;i<9;++i)presetButtons[static_cast<size_t>(i)].setBounds(juce::Rectangle<float>(1060*s,(123+i*16)*s,125*s,16*s).toNearestInt());for(int i=0;i<5;++i)tabs[static_cast<size_t>(i)].setBounds(juce::Rectangle<float>((510+i*94)*s,238*s,94*s,27*s).toNearestInt());settings.setBounds(juce::Rectangle<float>(1393*s,36*s,113*s,29*s).toNearestInt());scaleButton.setBounds(juce::Rectangle<float>(1394*s,319*s,109*s,24*s).toNearestInt());bypass.setBounds(juce::Rectangle<float>(1378*s,982*s,123*s,22*s).toNearestInt());}
void VocaEditor::timerCallback(){auto toDb=[](float v){return std::clamp(20*std::log10(std::max(v,1e-6f)),-60.f,6.f);};meterIn=std::max(toDb(processor.inputPeak.load()),meterIn-1.2f);meterOut=std::max(toDb(processor.outputPeak.load()),meterOut-1.2f);repaint();}
