void VocaEditor::drawKnob(juce::Graphics& g,const voca::Spec& a,float value){const float x=float(a.x),y=float(a.y),r=float(a.r),t=std::clamp((value-a.min)/(a.max-a.min),0.f,1.f);const float angle=(-135+270*t)*float(voca::pi/180);if(faceplate.isValid()){juce::Graphics::ScopedSaveState save(g);juce::Path clip;clip.addEllipse(x-r*.68f,y-r*.68f,r*1.36f,r*1.36f);g.reduceClipRegion(clip);const float initial=(a.initial-a.min)/(a.max-a.min);g.addTransform(juce::AffineTransform::rotation((t-initial)*float(voca::pi*1.5),x,y));g.drawImage(faceplate,{0.f,0.f,W,H});}else{
 for(int i=8;i>=1;--i){g.setColour(violet.withAlpha(.035f));g.fillEllipse(x-r-i,y-r-i,2*(r+i),2*(r+i));}g.setColour(juce::Colour(0xff252930));g.fillEllipse(x-r-2,y-r+2,2*r+4,2*r+4);g.setColour(juce::Colours::black);g.fillEllipse(x-r,y-r,2*r,2*r);
 for(int i=0;i<64;++i){const float start=(-225+i*270.f/64)*float(voca::pi/180);juce::Path segment;segment.addCentredArc(x,y,r-2,r-2,0,start,start+.065f,true);const float f=i/63.f;auto c=f<.4f?green.interpolatedWith(juce::Colour(0xff32efff),f/.4f):juce::Colour(0xff4940ff).interpolatedWith(violet,(f-.4f)/.6f);g.setColour(c.withAlpha(.9f));g.strokePath(segment,juce::PathStrokeType(4));}
 const float inner=r*.79f;g.setColour(juce::Colour(0xff08090c));g.fillEllipse(x-inner-2,y-inner-2,2*inner+4,2*inner+4);g.setColour(juce::Colour(0xffbfc1c1));g.fillEllipse(x-inner,y-inner,2*inner,2*inner);for(int i=0;i<72;++i){const float start=i*float(voca::pi*2/72)+angle;juce::Path wedge;wedge.addPieSegment(x-inner,y-inner,2*inner,2*inner,start,start+float(voca::pi*2/71),0);const float brightness=.62f+.22f*std::cos(start*2+.7f);g.setColour(juce::Colour::greyLevel(brightness));g.fillPath(wedge);g.strokePath(wedge,juce::PathStrokeType(.5f));}g.setColour(juce::Colour(0xffe5e8e9));g.drawEllipse(x-inner,y-inner,2*inner,2*inner,1);g.setColour(juce::Colour(0xff46494b));g.drawEllipse(x-inner+2,y-inner+2,2*inner-4,2*inner-4,1);g.setColour(juce::Colours::white.withAlpha(.7f));g.drawLine(x+std::sin(angle)*inner*.55f,y-std::cos(angle)*inner*.55f,x+std::sin(angle)*inner*.85f,y-std::cos(angle)*inner*.85f,2);}
 const int index=static_cast<int>(&a-voca::specs.data());float by=y+r+15,bx=x-43,bw=86,bh=26;if(index==voca::Input||index==voca::Output){by=233;bx=x-43;}else if(index==voca::Tune){by=180;bx=x-37;bw=74;bh=23;}else if(index>=voca::EqLow&&index<=voca::EqHigh){const char* f[]{"60 Hz","250 Hz","1.2 kHz","5.0 kHz","12.0 kHz"};box(g,f[index-voca::EqLow],x-40,451,80,23);by=478;bx=x-40;bw=80;bh=23;}else if(index>=voca::CompThreshold&&index<=voca::DeessAmount){by=459;bx=x-40;bw=80;}else if(index>=voca::Width&&index<=voca::Saturation){by=645;bh=25;if(index==voca::Width||index==voca::Heat)by=650;else{by=635;bw=61;bx=x-30;bh=22;}}else if(index>=voca::Clipper&&index<=voca::Imaging){by=847;bx=x-41;bw=82;}else if(index>=voca::LowEnd){by=849;bx=x-32;bw=64;}
 box(g,voca::format(static_cast<voca::Param>(index),value),bx,by,bw,bh,index>=voca::EqLow&&index<=voca::EqHigh?green:juce::Colours::white);
 if(!faceplate.isValid()){juce::String min=juce::String(a.min,0),max=juce::String(a.max,0);if(index==voca::DeessFreq){min="1k";max="10k";}if(index==voca::CompRatio){min="1:1";max="20:1";}if(index==voca::CompAttack)min="0.1";text(g,min,x-r-13,y+r-2,37,17,11);text(g,max,x+r-23,y+r-2,40,17,11);}
}
void VocaEditor::drawMeter(juce::Graphics& g,float level,int x,int y,int w,int h){g.setColour(juce::Colour(0xff121913));g.fillRoundedRectangle(float(x),float(y),float(w),float(h),3);const int steps=h/8;for(int i=0;i<steps;++i){const float db=-60+i*66.f/steps;auto c=db< -12?juce::Colour(0xff9cff31):db<0?juce::Colour(0xfff4ffab):juce::Colour(0xffff6243);g.setColour(db<=level?c:juce::Colour(0xff223026));g.fillRoundedRectangle(float(x+4),float(y+h-6-i*8),float(w-8),4,1);}g.setColour(juce::Colour(0xff8d9494));g.drawRoundedRectangle(float(x),float(y),float(w),float(h),3,1);}
void VocaEditor::drawWave(juce::Graphics& g){const juce::Rectangle<float> region(502,124,482,108);g.setColour(juce::Colour(0xff020407));g.fillRect(region);for(int i=0;i<32;++i){g.setColour(juce::Colour(0xff16202b));g.drawVerticalLine(502+i*15,124,232);}for(int i=0;i<5;++i){g.setColour(juce::Colour(0xff121a20));g.drawHorizontalLine(124+i*26,502,984);}const int pos=processor.wavePosition.load();for(int i=0;i<482;++i){const int index=(pos+i*512/482)%512;const float value=processor.waveform[static_cast<size_t>(index)].load();const float amplitude=std::clamp(std::abs(value)*51,0.f,51.f);const float t=i/482.f;const auto colour=t<.5f?green.interpolatedWith(juce::Colour(0xff24c5ff),t*2):juce::Colour(0xff24c5ff).interpolatedWith(violet,(t-.5f)*2);g.setColour(colour.withAlpha(.15f));g.drawVerticalLine(502+i,178-amplitude-4,178+amplitude+4);g.setColour(colour);g.drawVerticalLine(502+i,178-std::max(.4f,amplitude),178+std::max(.4f,amplitude));}text(g,processor.pitchHz.load()>0?"PITCH "+juce::String(processor.pitchHz.load(),0)+" Hz":"LIVE VOCAL / MASTER",505,216,180,15,10,false,juce::Colour(0xff98beb1));}
void VocaEditor::paint(juce::Graphics& g){g.addTransform(juce::AffineTransform::scale(getWidth()/W));g.drawImage(faceplate.isValid()?faceplate:metal,{0.f,0.f,W,H});for(int i=0;i<voca::NumKnobs;++i)drawKnob(g,voca::specs[i],static_cast<float>(knobs[static_cast<size_t>(i)]->getValue()));drawMeter(g,meterIn,214,64,23,196);drawMeter(g,meterIn,255,72,19,171);drawMeter(g,meterOut,1217,64,23,195);drawWave(g);box(g,juce::String(processor.rate.load()/1000,1)+" kHz",1397,95,110,27);const char* rates[]{"44.1 kHz","48 kHz","88.2 kHz","96 kHz","176.4 kHz","192 kHz"};for(int i=0;i<6;++i){const bool selected=std::abs(processor.rate.load()/1000-juce::String(rates[i]).getFloatValue())<.2;g.setColour(selected?juce::Colour(0xff4e18c9):juce::Colour(0xff101114));g.fillRect(1397,123+i*19,110,19);text(g,rates[i],1399,float(123+i*19),104,19,12,false,juce::Colours::white);}box(g,juce::String(processor.blockSize.load()),1397,270,110,27);g.setColour(juce::Colour(0xff080a10));g.fillRect(1060,122,125,149);for(int i=0;i<9;++i)presetButtons[static_cast<size_t>(i)].setColour(juce::TextButton::textColourOffId,(combos[2]->getSelectedId()==i+1)?green:juce::Colour(0xffdddddd));for(int i=0;i<5;++i)tabs[static_cast<size_t>(i)].setColour(juce::TextButton::textColourOffId,i==activeTab?green:juce::Colour(0xffd8d2f1));if(activeTab>0){const std::array<juce::Rectangle<float>,5> outlines{{{18,296,1058,211},{1083,296,148,211},{677,518,491,182},{195,518,477,182},{870,712,648,179}}};g.setColour(violet.withAlpha(.65f));g.drawRoundedRectangle(outlines[static_cast<size_t>(activeTab)],8,2);} }
